'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var hasProp = require( '@stdlib/assert/has-property' );
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var Scale = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Scale, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `round` property', function test( t ) {
	var v;

	v = new Scale({
		'name': 'xScale'
	});
	t.strictEqual( hasOwnProp( v, 'round' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'round' ), true, 'returns expected value' );
	t.strictEqual( isBoolean( v.round ), true, 'returns expected value' );

	v = new Scale({
		'name': 'xScale',
		'round': true
	});
	t.strictEqual( isBoolean( v.round ), true, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `round` property which throws an error if set to an invalid value', function test( t ) {
	var values;
	var i;
	var v;

	v = new Scale({
		'name': 'xScale'
	});

	values = [
		'5',
		5,
		NaN,
		null,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			v.round = value;
		};
	}
});

tape( 'the constructor returns an instance having a `round` property', function test( t ) {
	var scale;

	scale = new Scale({
		'name': 'xScale'
	});
	t.strictEqual( scale.round, false, 'returns expected value' );

	scale = new Scale({
		'name': 'xScale',
		'round': true
	});
	t.strictEqual( scale.round, true, 'returns expected value' );

	scale = new Scale({
		'name': 'xScale',
		'round': false
	});
	t.strictEqual( scale.round, false, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `round` property which can be set to a valid value', function test( t ) {
	var scale;

	scale = new Scale({
		'name': 'xScale'
	});

	scale.round = true;
	t.strictEqual( scale.round, true, 'returns expected value' );

	scale.round = false;
	t.strictEqual( scale.round, false, 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which emits an event when the `round` property is set to a new value', function test( t ) {
	var scale;
	var count;

	scale = new Scale({
		'name': 'xScale'
	});
	count = 0;

	scale.on( 'change', onChange );

	scale.round = true;
	t.strictEqual( count, 1, 'returns expected value' );

	scale.round = false;
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to the same value should not emit an event:
	scale.round = false;
	t.strictEqual( count, 2, 'returns expected value' );

	t.end();

	function onChange() {
		count += 1;
	}
});
